import React, { useState, useEffect, useCallback } from 'react';
import { Container, Row, Col, Card, Button, Form } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faTrash, faShoppingCart } from '@fortawesome/free-solid-svg-icons';
import axios from 'axios';

interface CartItem {
  id: number;
  title: string;
  coverImage: string;
  price: number;
  quantity: number;
}

const Cart: React.FC = () => {
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [total, setTotal] = useState(0);

  const calculateTotal = useCallback(() => {
    return cartItems.reduce((total, item) => total + (item.price * item.quantity), 0);
  }, [cartItems]);

  useEffect(() => {
    const fetchCartItems = async () => {
      try {
        // In a real application, replace with your actual API endpoint
        const response = await axios.get('/api/cart');
        setCartItems(response.data);
      } catch (error) {
        console.error('Error fetching cart items:', error);
      }
    };

    fetchCartItems();
  }, []);

  useEffect(() => {
    setTotal(calculateTotal());
  }, [calculateTotal]);

  const updateQuantity = async (itemId: number, newQuantity: number) => {
    if (newQuantity < 1) return;

    try {
      // In a real application, replace with your actual API endpoint
      await axios.put(`/api/cart/${itemId}`, { quantity: newQuantity });
      setCartItems(cartItems.map(item =>
        item.id === itemId ? { ...item, quantity: newQuantity } : item
      ));
    } catch (error) {
      console.error('Error updating quantity:', error);
    }
  };

  const removeItem = async (itemId: number) => {
    try {
      // In a real application, replace with your actual API endpoint
      await axios.delete(`/api/cart/${itemId}`);
      setCartItems(cartItems.filter(item => item.id !== itemId));
    } catch (error) {
      console.error('Error removing item:', error);
    }
  };

  const handleCheckout = () => {
    // Implement checkout functionality
    console.log('Proceeding to checkout');
  };

  if (cartItems.length === 0) {
    return (
      <Container className="py-5 text-center">
        <FontAwesomeIcon icon={faShoppingCart} size="3x" className="text-muted mb-3" />
        <h2>Giỏ hàng trống</h2>
        <p>Hãy thêm manga vào giỏ hàng của bạn</p>
      </Container>
    );
  }

  return (
    <Container className="py-4">
      <h1 className="mb-4">Giỏ hàng</h1>
      <Row>
        <Col md={8}>
          {cartItems.map((item) => (
            <Card key={item.id} className="mb-3">
              <Card.Body>
                <Row className="align-items-center">
                  <Col xs={3} md={2}>
                    <img src={item.coverImage} alt={item.title} className="img-fluid" />
                  </Col>
                  <Col xs={9} md={4}>
                    <h5>{item.title}</h5>
                    <p className="text-primary mb-0">
                      {item.price.toLocaleString('vi-VN')} đ
                    </p>
                  </Col>
                  <Col xs={6} md={3}>
                    <div className="d-flex align-items-center">
                      <Button
                        variant="outline-secondary"
                        size="sm"
                        onClick={() => updateQuantity(item.id, item.quantity - 1)}
                      >
                        -
                      </Button>
                      <Form.Control
                        type="number"
                        min="1"
                        value={item.quantity}
                        onChange={(e) => updateQuantity(item.id, parseInt(e.target.value))}
                        className="mx-2"
                        style={{ width: '60px' }}
                      />
                      <Button
                        variant="outline-secondary"
                        size="sm"
                        onClick={() => updateQuantity(item.id, item.quantity + 1)}
                      >
                        +
                      </Button>
                    </div>
                  </Col>
                  <Col xs={6} md={2} className="text-end">
                    <p className="fw-bold mb-0">
                      {(item.price * item.quantity).toLocaleString('vi-VN')} đ
                    </p>
                  </Col>
                  <Col xs={12} md={1} className="text-end">
                    <Button
                      variant="link"
                      className="text-danger p-0"
                      onClick={() => removeItem(item.id)}
                    >
                      <FontAwesomeIcon icon={faTrash} />
                    </Button>
                  </Col>
                </Row>
              </Card.Body>
            </Card>
          ))}
        </Col>
        <Col md={4}>
          <Card>
            <Card.Body>
              <h5 className="mb-3">Tổng đơn hàng</h5>
              <div className="d-flex justify-content-between mb-2">
                <span>Tạm tính:</span>
                <span>{total.toLocaleString('vi-VN')} đ</span>
              </div>
              <div className="d-flex justify-content-between mb-3">
                <span>Phí vận chuyển:</span>
                <span>0 đ</span>
              </div>
              <hr />
              <div className="d-flex justify-content-between mb-3">
                <strong>Tổng cộng:</strong>
                <strong>{total.toLocaleString('vi-VN')} đ</strong>
              </div>
              <Button variant="primary" className="w-100" onClick={handleCheckout}>
                Tiến hành thanh toán
              </Button>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default Cart;
